/* Start here entry for nuclear-reactions (demos/lib/starthere/nuclear-reactions.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"Rutherford's reaction α + ¹⁴N → p + ¹⁷O takes in 1.19 MeV. Will an alpha particle with 1.30 MeV make it go?","q_es":"La reacción de Rutherford α + ¹⁴N → p + ¹⁷O absorbe 1.19 MeV. ¿Una partícula alfa con 1.30 MeV la hará ocurrir?","setup":"","do":"The products outweigh the reactants, so <b>Q = (m before − m after)c²</b> reads −1.1919 MeV. Decide whether an alpha with 1.30 MeV, more than |Q|, can make the reaction happen. Set <b>Projectile kinetic energy K</b> to 1.30 MeV, press <b>Fire</b> and read <b>Allowed by energy</b>; then raise K until it says yes.","do_es":"Los productos pesan más que los reactivos, así que <b>Q = (m antes − m después)c²</b> marca −1.1919 MeV. Decide si una alfa con 1.30 MeV, más que |Q|, puede producir la reacción. Pon <b>Energía cinética K del proyectil</b> en 1.30 MeV, presiona <b>Disparar</b> y lee <b>Permitida por la energía</b>; luego sube K hasta que diga sí.","see":"It reads no at 1.30 MeV, and yes only from the <b>Threshold kinetic energy</b>, 1.5326 MeV. Momentum is conserved, so the products must keep moving and carry off kinetic energy; only what is left after that can pay for the extra mass. The threshold is close to |Q|(1 + m<sub>α</sub>/m<sub>N</sub>) = 1.19 × 1.29 = 1.53 MeV.","see_es":"Marca no a 1.30 MeV, y sí solo a partir de la <b>Energía cinética umbral</b>, 1.5326 MeV. El momento se conserva, así que los productos deben seguir moviéndose y llevarse energía cinética; solo lo que queda después de eso puede pagar la masa de más. El umbral es cercano a |Q|(1 + m<sub>α</sub>/m<sub>N</sub>) = 1.19 × 1.29 = 1.53 MeV.","explore":[{"setup":"set=chR~8!labBlind~0!g%3AviewSeg~ch!g%3AdimSeg~3d!g%3Apresets~chSphere","do":"<b>Bare ²³⁵U sphere</b>: a ball of uranium 235 metal 8.00 cm in radius, 40.5 kg. Decide whether a chain reaction in it grows or dies out, then press <b>Play</b> and read <b>k, mean after generation 5</b>. Set <b>Radius of the sphere R</b> to 9.00 cm, press <b>Reset</b> and <b>Play</b>, and read k again.","do_es":"<b>Esfera desnuda de ²³⁵U</b>: una esfera de uranio 235 metálico de 8.00 cm de radio, 40.5 kg. Decide si una reacción en cadena en ella crece o se apaga, luego presiona <b>Iniciar</b> y lee <b>k, media después de la generación 5</b>. Pon <b>Radio de la esfera R</b> en 9.00 cm, presiona <b>Reiniciar</b> e <b>Iniciar</b>, y lee k otra vez.","see":"At 8 cm k is about 0.96: some 61 % of the neutrons leak out through the surface (<b>Leaked out this generation</b>), so each fission leads to fewer than one more. At 9 cm k is about 1.06 and the chain grows. Fissions grow with the volume, as R³, but escape only with the surface, as R², so there is a critical size: about 8.3 cm and 45 kg in this model, against 46 kg from a full calculation.","see_es":"A 8 cm k es de unos 0.96: cerca del 61 % de los neutrones se escapa por la superficie (<b>Escaparon en esta generación</b>), así que cada fisión lleva a menos de una más. A 9 cm k es de unos 1.06 y la cadena crece. Las fisiones crecen con el volumen, como R³, pero los escapes solo con la superficie, como R², así que hay un tamaño crítico: unos 8.3 cm y 45 kg en este modelo, contra 46 kg de un cálculo completo."},{"setup":"set=fuT~7.2!labBlind~0!g%3AviewSeg~fu!g%3Apresets~fuSun","do":"<b>The Sun's core</b>: protons at 1.57 × 10⁷ K. Read <b>kT</b> and <b>Coulomb barrier at contact</b>. Decide at what energy the protons that do fuse collide: near kT, near the barrier, or in between. Then read <b>Gamow peak, measured on the curve</b>.","do_es":"<b>El núcleo del Sol</b>: protones a 1.57 × 10⁷ K. Lee <b>kT</b> y <b>Barrera de Coulomb al contacto</b>. Decide a qué energía chocan los protones que sí se fusionan: cerca de kT, cerca de la barrera o en medio. Luego lee <b>Pico de Gamow, medido sobre la curva</b>.","see":"kT is 1.353 keV, about 440 times below the 600 keV barrier, and the protons that fuse collide at 6.088 keV, in between. Faster protons are rare (the tail of the Maxwell–Boltzmann distribution) and slower ones almost never tunnel through the barrier, so the product of the two peaks there. Going over the barrier instead would take 6.96 × 10⁹ K (<b>T at which kT equals the barrier</b>).","see_es":"kT es 1.353 keV, unas 440 veces menos que la barrera de 600 keV, y los protones que se fusionan chocan a 6.088 keV, en medio. Los protones más rápidos son escasos (la cola de la distribución de Maxwell–Boltzmann) y los más lentos casi nunca atraviesan la barrera por efecto túnel, así que el producto de las dos cosas tiene su máximo ahí. Pasar por encima de la barrera requeriría 6.96 × 10⁹ K (<b>T a la que kT es igual a la barrera</b>)."},{"setup":"set=doA~9!doR~1!doX~0!doT~2!labBlind~0!g%3AviewSeg~do!g%3AdimSeg~3d!g%3Apresets~doCs","do":"<b>¹³⁷Cs source</b>: a 1 GBq source 1.00 m from the meter gives 83.41 µSv/h. Predict the reading at 2 m, then set <b>Distance to the meter r</b> to 2.00 m and read <b>Equivalent dose rate (w_R = 1)</b>.","do_es":"<b>Fuente de ¹³⁷Cs</b>: una fuente de 1 GBq a 1.00 m del medidor da 83.41 µSv/h. Predice la lectura a 2 m, luego pon <b>Distancia al medidor r</b> en 2.00 m y lee <b>Tasa de dosis equivalente (w_R = 1)</b>.","see":"20.85 µSv/h, a quarter. The gamma rays from a point source spread over a sphere of area 4πr², so the dose rate goes as 1/r²: twice as far, a quarter of the dose. Stepping back is the cheapest shielding there is.","see_es":"20.85 µSv/h, la cuarta parte. Los rayos gamma de una fuente puntual se reparten sobre una esfera de área 4πr², así que la tasa de dosis va como 1/r²: al doble de distancia, la cuarta parte de la dosis. Alejarse es el blindaje más barato que hay."}]});
